    'rep.n3' => ['en'=>'a short account of the demonstrable effect','cy'=>'cyfrif byr o’r effaith ddangosadwy'],
    'rep.phase' => ['en'=>'Use this service to report a suspected Excess Time Event.','cy'=>'Defnyddiwch y gwasanaeth hwn i roi gwybod am Ddigwyddiad Amser Dros Ben tybiedig.'],

    'cook.h1' => ['en'=>'Cookies','cy'=>'Cwcis'],
    'cook.p' => ['en'=>'This service puts small files (known as ‘cookies’) on your device.','cy'=>'Mae’r gwasanaeth hwn yn rhoi ffeiliau bach (a elwir yn ‘cwcis’) ar eich dyfais.'],
    'cook.ess' => ['en'=>'Essential cookies','cy'=>'Cwcis hanfodol'],
    'cook.ess.p' => ['en'=>'These cookies keep the service working. They remember that you have seen the cookie message, and they remember which pages of the Department you have opened in this browser. That record is kept only on your device.','cy'=>'Mae’r cwcis hyn yn cadw’r gwasanaeth i weithio. Maent yn cofio eich bod wedi gweld neges y cwcis, a pha dudalennau o’r Adran a agorwyd gennych yn y porwr hwn. Cedwir y cofnod hwnnw ar eich dyfais yn unig.'],
    'cook.lang' => ['en'=>'Language','cy'=>'Iaith'],
    'cook.lang.p' => ['en'=>'Your language choice is stored as an essential cookie so that the service remains in Cymraeg or English as you move between pages.','cy'=>'Cedwir eich dewis iaith fel cwci hanfodol fel bod y gwasanaeth yn parhau yn Gymraeg neu yn Saesneg wrth i chi symud rhwng tudalennau.'],

    'acc.h1' => ['en'=>'Accessibility statement','cy'=>'Datganiad hygyrchedd'],
    'acc.p1' => ['en'=>'This website is run by the Department of Excess Time. We want as many people as possible to be able to use this website.','cy'=>'Mae’r wefan hon yn cael ei rhedeg gan Adran Amser Dros Ben. Rydym eisiau i gynifer o bobl â phosibl allu defnyddio’r wefan hon.'],
    'acc.p2' => ['en'=>'This statement was prepared on 1 April 2026. It was last reviewed on 1 September 2026.','cy'=>'Paratowyd y datganiad hwn ar 1 Ebrill 2026. Cafodd ei adolygu ddiwethaf ar 1 Medi 2026.'],
    'acc.p3' => ['en'=>'If you need information on this website in a different format, contact the Department at Cathays Park.','cy'=>'Os oes angen gwybodaeth ar y wefan hon arnoch mewn fformat gwahanol, cysylltwch â’r Adran ym Mharc Cathays.'],

    'priv.h1' => ['en'=>'Privacy notice','cy'=>'Hysbysiad preifatrwydd'],
    'priv.p1' => ['en'=>'The Department of Excess Time is the data controller. Some records describe hours that failed to arrive. Those records remain personal data.','cy'=>'Adran Amser Dros Ben yw’r rheolydd data. Mae rhai cofnodion yn disgrifio oriau a fethodd â chyrraedd. Mae’r cofnodion hynny’n parhau’n ddata personol.'],
    'priv.p2' => ['en'=>'A subject access request will be answered within the statutory period unless the record is of an event that has not yet become eligible.','cy'=>'Atebir cais mynediad gwrthrych o fewn y cyfnod statudol oni bai bod y cofnod yn ymwneud â digwyddiad nad yw eto’n gymwys.'],

    '404.h1' => ['en'=>'Page not found','cy'=>'Ni chanfuwyd y dudalen'],
    '404.p' => ['en'=>'This address is not on the public estate. If you arrived from a publication, the edition may have been superseded.','cy'=>'Nid yw’r cyfeiriad hwn ar yr ystâd gyhoeddus. Os cyrhaeddoch o gyhoeddiad, efallai bod yr argraffiad wedi’i ddisodli.'],

