    'off.circ' => ['en'=>'Circular: Regional office closures','cy'=>'Cylchlythyr: cau swyddfeydd rhanbarthol'],
    'off.enquiries' => ['en'=>'Most offices are closed due to budget reductions. Enquiries transfer to Cardiff.','cy'=>'Mae’r rhan fwyaf o swyddfeydd ar gau oherwydd toriadau cyllideb. Trosglwyddir ymholiadau i Gaerdydd.'],

    'foi.p0' => ['en'=>'The Department is a public authority for the purposes of the Freedom of Information Act 2000 and the Environmental Information Regulations, where they apply.','cy'=>'Mae’r Adran yn awdurdod cyhoeddus at ddibenion Deddf Rhyddid Gwybodaeth 2000 a’r Rheoliadau Gwybodaeth Amgylcheddol, lle maent yn gymwys.'],
    'foi.p2' => ['en'=>'Some records describe events that have not yet become eligible for disclosure. Eligibility is a matter of date, not of convenience. The Department will neither confirm nor deny a holding where to do so would itself constitute an Excess Time Event.','cy'=>'Mae rhai cofnodion yn disgrifio digwyddiadau nad ydynt eto’n gymwys i’w datgelu. Mater o ddyddiad yw cymhwysedd, nid cyfleustra. Ni fydd yr Adran yn cadarnhau nac yn gwadu daliad lle byddai gwneud hynny ynddo’i hun yn gyfystyr â Digwyddiad Amser Dros Ben.'],
    'foi.ncnd' => ['en'=>'We will neither confirm nor deny holdings that would themselves constitute an Excess Time Event.','cy'=>'Ni fyddwn yn cadarnhau nac yn gwadu daliadau a fyddai ynddynt eu hunain yn gyfystyr â Digwyddiad Amser Dros Ben.'],
    'foi.write' => ['en'=>'Write to Records, Cardiff, or use the contact page. Quote FOIA. Do not send recovered hours with your request.','cy'=>'Ysgrifennwch at Gofnodion, Caerdydd, neu defnyddiwch y dudalen gysylltu. Dyfynnwch FOIA. Peidiwch ag anfon oriau a adenillwyd gyda’ch cais.'],

    'res.its.p1' => ['en'=>'The Institute sits inside the Department. It maintains continuous watch over indicators of temporal imbalance, in support of the first obligation: Observe.','cy'=>'Mae’r Sefydliad y tu mewn i’r Adran. Mae’n cadw gwylfa barhaus dros ddangosyddion anghydbwysedd amserol, i gefnogi’r rhwymedigaeth gyntaf: Arsylwi.'],
    'res.its.p2' => ['en'=>'It does not regulate clocks, calendars, memory or history. Its concern begins when measurable continuity diverges from ordinary expectation.','cy'=>'Nid yw’n rheoleiddio clociau, calendrau, cof na hanes. Mae ei bryder yn dechrau pan fydd parhad mesuradwy yn gwyro oddi wrth ddisgwyliad cyffredin.'],
    'res.its.p3' => ['en'=>'Instrument 13 remains under civil oversight. The machine does not predict. It measures relation.','cy'=>'Mae Offeryn 13 yn parhau o dan oruchwyliaeth sifil. Nid yw’r peiriant yn rhagweld. Mae’n mesur perthynas.'],
    'res.arc.p1' => ['en'=>'The archive preserves accurate and impartial records of all recognised Excess Time Events. Contradiction is retained. It is not resolved.','cy'=>'Mae’r archif yn cadw cofnodion cywir a diduedd o bob Digwyddiad Amser Dros Ben cydnabyddedig. Cedwir gwrthddywediad. Nid yw’n cael ei ddatrys.'],
    'res.arc.p2' => ['en'=>'Authorised researchers may apply for access on form DET-78. Some holdings are not yet eligible.','cy'=>'Gall ymchwilwyr awdurdodedig wneud cais am fynediad ar ffurflen DET-78. Nid yw rhai daliadau eto’n gymwys.'],
    'res.arc.p3' => ['en'=>'Catalogue mark TTG-13 is retained with the file. It is not a disposal class.','cy'=>'Cedwir marc catalog TTG-13 gyda’r ffeil. Nid dosbarth gwaredu mohono.'],
    'res.wp.p' => ['en'=>'Working papers are not a statement of departmental policy.','cy'=>'Nid yw papurau gwaith yn ddatganiad o bolisi adrannol.'],
    'res.wp.044' => ['en'=>'DET-RES-044 Geometry of unplaced hours','cy'=>'DET-RES-044 Geometreg oriau heb eu gosod'],
    'res.wp.051' => ['en'=>'DET-RES-051 Coincidence as insufficient explanation','cy'=>'DET-RES-051 Cyd-ddigwyddiad fel esboniad annigonol'],
    'res.pr.p1' => ['en'=>'Working papers are reviewed before they may be cited in operational instruction. Reviewers are asked for method, not belief.','cy'=>'Adolygir papurau gwaith cyn y gellir eu dyfynnu mewn cyfarwyddyd gweithredol. Gofynnir i adolygwyr am ddull, nid am gred.'],
    'res.geo.p1' => ['en'=>'Some hours have a time and no agreed place. The Institute maps them. It does not assign an address that has not been claimed.','cy'=>'Mae gan rai oriau amser a dim lle cytunedig. Mae’r Sefydliad yn eu mapio. Nid yw’n rhoi cyfeiriad nad yw wedi’i hawlio.'],
    'res.geo.p2' => ['en'=>'Structure first. Interpretation later.','cy'=>'Strwythur yn gyntaf. Dehongliad yn ddiweddarach.'],
    'res.hist.codex' => ['en'=>'DET-CODEX-001 Founding Codex Edition 1','cy'=>'DET-CODEX-001 Codex Sefydlu Argraffiad 1'],
    'res.hist.1951' => ['en'=>'DET-HIST-1951 Instrument of Establishment','cy'=>'DET-HIST-1951 Offeryn Sefydlu'],
    'res.hist.1963' => ['en'=>'DET-HIST-1963 Minute: Abercrave station','cy'=>'DET-HIST-1963 Cofnod: gorsaf Abercraf'],
    'res.field.p' => ['en'=>'The unredacted Cribarth series is withheld under section 31 pending a further series. The tables disagreed.','cy'=>'Mae cyfres Cribarth heb ei golygu yn cael ei hatal o dan adran 31 hyd nes cyfres bellach. Roedd y tablau’n anghytuno.'],
    'res.field.088' => ['en'=>'DET-FIELD-088 Cribarth night readings (extract)','cy'=>'DET-FIELD-088 Darlleniadau nos Cribarth (dyfyniad)'],
    'res.field.091' => ['en'=>'DET-FIELD-091 Cardiff dock displacement','cy'=>'DET-FIELD-091 Dadleoli dociau Caerdydd'],
    'res.apply' => ['en'=>'Apply for research access','cy'=>'Gwneud cais am fynediad ymchwil'],
    'res.pubs' => ['en'=>'Research publications','cy'=>'Cyhoeddiadau ymchwil'],
    'res.reading' => ['en'=>'Reading room by appointment. Authorised researchers only. Apply with DET-78.','cy'=>'Ystafell ddarllen drwy apwyntiad. Ymchwilwyr awdurdodedig yn unig. Gwnewch gais gyda DET-78.'],

    'guid.afternoon' => ['en'=>'If an afternoon is missing','cy'=>'Os yw prynhawn ar goll'],
    'guid.afternoon.p' => ['en'=>'Continue where you can. Do not attempt to recover the hours yourself. Notify the Department on form DET-44 if the absence produces a demonstrable effect.','cy'=>'Parhewch lle y gallwch. Peidiwch â cheisio adennill yr oriau eich hun. Hysbyswch yr Adran ar ffurflen DET-44 os yw’r absenoldeb yn cynhyrchu effaith ddangosadwy.'],
    'guid.day' => ['en'=>'If a day cannot be reconstructed','cy'=>'Os na ellir ail-lunio diwrnod'],
    'guid.day.p' => ['en'=>'The Department does not regulate memory. You may request an assessment on form DET-61.','cy'=>'Nid yw’r Adran yn rheoleiddio cof. Gallwch ofyn am asesiad ar ffurflen DET-61.'],
    'guid.report' => ['en'=>'If you wish to report an incident','cy'=>'Os ydych yn dymuno rhoi gwybod am ddigwyddiad'],
    'guid.report.p' => ['en'=>'Use Report an Excess Time Event. Form DET-01.','cy'=>'Defnyddiwch Rhoi gwybod am Ddigwyddiad Amser Dros Ben. Ffurflen DET-01.'],
    'guid.schools.btn' => ['en'=>'Schools','cy'=>'Ysgolion'],
    'guid.schools.p' => ['en'=>'Schools service and DET-GUID-009.','cy'=>'Gwasanaeth ysgolion a DET-GUID-009.'],

    'com.p1' => ['en'=>'Programmes exist to reduce harm arising from temporal displacement wherever reasonably practicable. They are not cultural funding.','cy'=>'Mae rhaglenni’n bodoli i leihau niwed sy’n deillio o ddadleoli amserol lle y mae’n rhesymol ymarferol. Nid cyllid diwylliannol mohonynt.'],
    'com.p2' => ['en'=>'Local authorities and community groups in Wales may nominate a programme on form DET-17.','cy'=>'Gall awdurdodau lleol a grwpiau cymunedol yng Nghymru enwebu rhaglen ar ffurflen DET-17.'],
    'com.start' => ['en'=>'Start a nomination','cy'=>'Dechrau enwebiad'],
    'com.frame' => ['en'=>'DET-COM-012 Community programmes framework','cy'=>'DET-COM-012 Fframwaith rhaglenni cymunedol'],

    'sch.p1' => ['en'=>'The Department does not teach history. It does not regulate memory. It will, on request, speak to a maintained school in Wales about continuity.','cy'=>'Nid yw’r Adran yn addysgu hanes. Nid yw’n rheoleiddio cof. Bydd, ar gais, yn siarad ag ysgol a gynhelir yng Nghymru am barhad.'],
    'sch.p2' => ['en'=>'Pupils should be told that the existence of the Department is not evidence that they are at unusual risk. Members of the public are encouraged to continue with their ordinary affairs.','cy'=>'Dylid dweud wrth ddisgyblion nad yw bodolaeth yr Adran yn dystiolaeth eu bod mewn perygl anarferol. Anogir aelodau’r cyhoedd i barhau â’u materion arferol.'],
    'sch.p3' => ['en'=>'Visits last one hour. Officers will not take questions on 1951.','cy'=>'Mae ymweliadau’n para un awr. Ni fydd swyddogion yn cymryd cwestiynau ar 1951.'],
    'sch.visit' => ['en'=>'Request a visit','cy'=>'Gofyn am ymweliad'],
    'sch.guid' => ['en'=>'DET-GUID-009 Schools: teaching temporal continuity','cy'=>'DET-GUID-009 Ysgolion: addysgu parhad amserol'],

    'wel.maxim' => ['en'=>'No person’s time shall be deemed surplus solely by reason of economic unproductivity.','cy'=>'Ni chaiff amser neb ei ystyried yn ormodol oherwydd diffyg cynhyrchiant economaidd yn unig.'],
    'wel.hours' => ['en'=>'Hours devoted to friendship remain hours. Hours devoted to mourning remain hours. Hours devoted to wandering remain hours. Hours devoted to wonder remain hours.','cy'=>'Mae oriau a neilltuir i gyfeillgarwch yn parhau’n oriau. Mae oriau a neilltuir i alaru yn parhau’n oriau. Mae oriau a neilltuir i grwydro yn parhau’n oriau. Mae oriau a neilltuir i ryfeddod yn parhau’n oriau.'],
    'wel.p2' => ['en'=>'Support is offered to restore recoverable continuity. It is not a benefit for unused time.','cy'=>'Cynigir cymorth i adfer parhad adenilladwy. Nid budd-dal am amser nas defnyddiwyd mohono.'],
    'wel.p3' => ['en'=>'If you have suffered chronological damage arising from a recognised event, use form DET-22. If hours have returned, use form DET-14.','cy'=>'Os ydych wedi dioddef difrod cronolegol yn deillio o ddigwyddiad cydnabyddedig, defnyddiwch ffurflen DET-22. Os yw oriau wedi dychwelyd, defnyddiwch ffurflen DET-14.'],
    'wel.claim' => ['en'=>'Start a claim','cy'=>'Dechrau hawliad'],
    'wel.pol' => ['en'=>'DET-POL-007 Temporal Welfare Policy','cy'=>'DET-POL-007 Polisi Lles Amserol'],

    'acc.res.p1' => ['en'=>'Authorised researchers may apply to consult holdings of the Institute for Temporal Studies.','cy'=>'Gall ymchwilwyr awdurdodedig wneud cais i ymgynghori â daliadau Sefydliad Astudiaethau Amserol.'],
    'acc.res.p2' => ['en'=>'Some holdings are not yet eligible. Eligibility is a matter of date, not of convenience.','cy'=>'Nid yw rhai daliadau eto’n gymwys. Mater o ddyddiad yw cymhwysedd, nid cyfleustra.'],
    'acc.res.p3' => ['en'=>'You will need your name, affiliation, and the document numbers you wish to see.','cy'=>'Bydd angen eich enw, eich perthynas, a rhifau’r dogfennau yr ydych yn dymuno eu gweld.'],

