    'car.apply.cf' => ['en'=>'Apply through Cardiff','cy'=>'Gwneud cais drwy Gaerdydd'],
    'car.profiles' => ['en'=>'Success profiles apply. Charge is not a requirement for civil service posts unless stated.','cy'=>'Mae proffiliau llwyddiant yn gymwys. Nid yw tâl yn ofyniad ar gyfer swyddi gwasanaeth sifil oni nodir.'],
    'car.cs.lede' => ['en'=>'Civil Service vacancies in the Department of Excess Time. Cardiff, unless otherwise stated.','cy'=>'Swyddi gwag Gwasanaeth Sifil yn Adran Amser Dros Ben. Caerdydd, oni nodir fel arall.'],
    'car.public' => ['en'=>'These are public appointments. They are advertised as other Welsh Government posts are advertised.','cy'=>'Penodiadau cyhoeddus yw’r rhain. Fe’u hysbysebir fel y mae swyddi eraill Llywodraeth Cymru yn cael eu hysbysebu.'],
    'contact.enquiries' => ['en'=>'General enquiries:','cy'=>'Ymholiadau cyffredinol:'],
    'contact.incidents' => ['en'=>'Incidents: use DET-01. Do not email recovered hours.','cy'=>'Digwyddiadau: defnyddiwch DET-01. Peidiwch ag e-bostio oriau a adenillwyd.'],
    'contact.press' => ['en'=>'Press: the Department does not comment on coincidence.','cy'=>'Y wasg: nid yw’r Adran yn sylwebu ar gyd-ddigwyddiad.'],
