    'doc.status' => ['en'=>'Status','cy'=>'Statws'],
    'doc.arrival' => ['en'=>'On arrival','cy'=>'Wrth gyrraedd'],
    'man.p1' => ['en'=>'This manual is the standing instruction for officers of the Department. It does not confer authority over the lawful passage of time itself.','cy'=>'Y llawlyfr hwn yw’r cyfarwyddyd sefydlog i swyddogion yr Adran. Nid yw’n rhoi awdurdod dros basio cyfreithlon amser ei hun.'],
    'man.l1' => ['en'=>'Observe. Do not restore until the event is recognised.','cy'=>'Arsylwch. Peidiwch ag adfer nes y cydnabyddir y digwyddiad.'],
    'man.l2' => ['en'=>'Record. Use form DET-01. Do not improve the facts.','cy'=>'Cofnodwch. Defnyddiwch ffurflen DET-01. Peidiwch â gwella’r ffeithiau.'],
    'man.l3' => ['en'=>'Protect. Reduce harm wherever reasonably practicable.','cy'=>'Diogelwch. Lleihau niwed lle y mae’n rhesymol ymarferol.'],
    'man.l4' => ['en'=>'Restore. Only recoverable continuity. Only where lawful.','cy'=>'Adferwch. Parhad adenilladwy yn unig. Dim ond lle y mae’n gyfreithlon.'],
    'man.coin' => ['en'=>'Coincidence is not an explanation. TTG-13 is not a procedure.','cy'=>'Nid esboniad yw cyd-ddigwyddiad. Nid gweithdrefn yw TTG-13.'],
    'tech.p1' => ['en'=>'The public chronometer programme measures relation. It does not predict. Field units are issued only against a departmental instruction.','cy'=>'Mae rhaglen y cronomedr cyhoeddus yn mesur perthynas. Nid yw’n rhagweld. Cyhoeddir unedau maes dim ond yn erbyn cyfarwyddyd adrannol.'],
    'tech.p2' => ['en'=>'The annex lists serials. One code recurs. It is not a serial.','cy'=>'Mae’r atodiad yn rhestru cyfresi. Mae un cod yn ailadrodd. Nid cyfres mohono.'],
    'wel.if' => ['en'=>'If hours fail to arrive','cy'=>'Os bydd oriau’n methu â chyrraedd'],
    'wel.if.p' => ['en'=>'Most citizens will never knowingly encounter an Excess Time Event. Where an afternoon does not arrive where it was expected:','cy'=>'Ni fydd y rhan fwyaf o ddinasyddion byth yn dod ar draws Digwyddiad Amser Dros Ben yn wybodus. Pan na fydd prynhawn yn cyrraedd lle’r oedd disgwyl:'],
    'wel.if.1' => ['en'=>'Continue with your ordinary affairs.','cy'=>'Parhewch â’ch materion arferol.'],
    'wel.if.2' => ['en'=>'If the absence produces demonstrable effects, report an incident.','cy'=>'Os yw’r absenoldeb yn cynhyrchu effeithiau dangosadwy, rhowch wybod am ddigwyddiad.'],
    'wel.if.3' => ['en'=>'Do not attempt to recover hours yourself.','cy'=>'Peidiwch â cheisio adennill oriau eich hun.'],
    'wel.clocks' => ['en'=>'The Department does not regulate clocks, calendars, memory or history.','cy'=>'Nid yw’r Adran yn rheoleiddio clociau, calendrau, cof na hanes.'],
    'cons.p1' => ['en'=>'This consultation seeks views on proposed Excess Time (Wales) Regulations. It closes on 23 October 2026.','cy'=>'Mae’r ymgynghoriad hwn yn gofyn am farn ar Reoliadau Amser Dros Ben (Cymru) arfaethedig. Mae’n cau ar 23 Hydref 2026.'],
    'cons.p2' => ['en'=>'Responses should be sent to the address on the contact page. Do not send recovered hours with your response.','cy'=>'Dylid anfon ymatebion i’r cyfeiriad ar y dudalen gysylltu. Peidiwch ag anfon oriau a adenillwyd gyda’ch ymateb.'],
    'ar.p1' => ['en'=>'Laid before the Senedd, August 2026. The Department continued to administer excess temporal capacity arising in Wales and associated jurisdictions.','cy'=>'Wedi’i osod gerbron y Senedd, Awst 2026. Parhaodd yr Adran i weinyddu capasiti amserol dros ben sy’n codi yng Nghymru ac awdurdodaethau cysylltiedig.'],
    'ar.p2' => ['en'=>'Cardiff remains the public counter. Abercrave remains a field station. Bristol, Manchester, Edinburgh and Belfast remain closed due to budget reductions.','cy'=>'Caerdydd yw’r cownter cyhoeddus o hyd. Gorsaf faes yw Abercraf o hyd. Mae Bryste, Manceinion, Caeredin a Béal Feirste ar gau o hyd oherwydd toriadau cyllideb.'],
    'ar.p3' => ['en'=>'Recruitment of Assistant Temporal Survey Officers opened in July.','cy'=>'Agorwyd recriwtio Swyddogion Arolwg Amserol Cynorthwyol ym mis Gorffennaf.'],
    'his51.p1' => ['en'=>'The Department of Excess Time was established in 1951 as an executive department operating under ministerial authority, with duties across Wales and the United Kingdom.','cy'=>'Sefydlwyd Adran Amser Dros Ben ym 1951 fel adran weithredol yn gweithredu o dan awdurdod gweinidogol, gyda dyletswyddau ar draws Cymru a’r Deyrnas Unedig.'],
    'his51.p2' => ['en'=>'The founding principle is set out in the Codex. Readers are advised not to seek complete understanding in advance.','cy'=>'Gosodir yr egwyddor sefydlu yn y Codex. Cynghorir darllenwyr i beidio â cheisio dealltwriaeth gyflawn ymlaen llaw.'],
    'his08.p1' => ['en'=>'A civilian body later described 2008 as a founding at Cardiff. The Department notes the papers. It does not adopt them.','cy'=>'Disgrifiodd corff sifil yn ddiweddarach 2008 fel sefydlu yng Nghaerdydd. Mae’r Adran yn nodi’r papurau. Nid yw’n eu mabwysiadu.'],
    'his08.p2' => ['en'=>'Contradiction is not error. It is evidence of overlap.','cy'=>'Nid gwall yw gwrthddywediad. Tystiolaeth o orgyffwrdd yw.'],
